import { describe, beforeAll, test, expect } from 'vitest'
import { searchClient, dataset, meilisearchClient } from './assets/utils.js'

describe('Facet stats tests', () => {
  beforeAll(async () => {
    await meilisearchClient.deleteIndex('movies').waitTask()
    await meilisearchClient
      .index('movies')
      .updateFilterableAttributes(['genres', 'release_date', 'id'])
      .waitTask()
    await meilisearchClient.index('movies').addDocuments(dataset).waitTask()
  })

  test('Facet stats on an empty facets array', async () => {
    const response = await searchClient.search([
      {
        indexName: 'movies',
        params: {
          query: '',
          facets: [],
        },
      },
    ])

    expect(response.results[0].facets_stats?.release_date).toEqual(undefined)
  })

  test('Facet stats on a facet with no numeric values', async () => {
    const response = await searchClient.search([
      {
        indexName: 'movies',
        params: {
          query: '',
          facets: ['genres'],
        },
      },
    ])

    expect(response.results[0].facets_stats?.genres).toEqual(undefined)
  })

  test('Facet stats on two facet', async () => {
    const response = await searchClient.search([
      {
        indexName: 'movies',
        params: {
          query: '',
          facets: ['release_date', 'id'],
        },
      },
    ])

    expect(response.results[0].facets_stats?.release_date).toEqual({
      avg: 0,
      max: 1065744000,
      min: 233366400,
      sum: 0,
    })
    expect(response.results[0].facets_stats?.id).toEqual({
      avg: 0,
      max: 30,
      min: 2,
      sum: 0,
    })
  })
})

import { describe, beforeAll, test, expect } from 'vitest'
import {
  searchClient,
  dataset,
  type Movies,
  meilisearchClient,
} from './assets/utils.js'

import { splitSortString } from '../src/contexts/sort-context.js'

describe('Sort browser test', () => {
  beforeAll(async () => {
    await meilisearchClient.deleteIndex('movies').waitTask()
    await meilisearchClient
      .index('movies')
      .updateSettings({
        sortableAttributes: ['release_date', 'title'],
      })
      .waitTask()

    await meilisearchClient.index('movies').addDocuments(dataset).waitTask()
  })

  test('sort-by one field', async () => {
    const response = await searchClient.search<Movies>([
      {
        indexName: 'movies:release_date:desc',
        params: {
          query: '',
          hitsPerPage: 1,
        },
      },
    ])

    const hits = response.results[0].hits
    expect(hits.length).toBe(1)
  })

  test('sort-by mutiple fields', async () => {
    const response = await searchClient.search<Movies>([
      {
        indexName: 'movies:release_date:desc,title:asc',
        params: {
          query: '',
          hitsPerPage: 1,
        },
      },
    ])

    const hits = response.results[0].hits
    expect(hits.length).toBe(1)
  })

  test('split multiple sorting rules', () => {
    const sortRules = splitSortString(
      '_geoPoint(37.8153, -122.4784):asc,title:asc,description:desc'
    )

    expect(sortRules).toEqual([
      '_geoPoint(37.8153, -122.4784):asc',
      'title:asc',
      'description:desc',
    ])
  })

  test('split multiple sorting rules in different order', () => {
    const sortRules = splitSortString(
      'title:asc,_geoPoint(37.8153, -122.4784):asc,description:desc'
    )

    expect(sortRules).toEqual([
      'title:asc',
      '_geoPoint(37.8153, -122.4784):asc',
      'description:desc',
    ])
  })

  test('split one sorting rule', () => {
    const sortRules = splitSortString('_geoPoint(37.8153, -122.4784):asc')

    expect(sortRules).toEqual(['_geoPoint(37.8153, -122.4784):asc'])
  })

  test('split no sorting rule', () => {
    const sortRules = splitSortString('')

    expect(sortRules).toEqual([])
  })
})

import { describe, beforeAll, test, expect, vi } from 'vitest'
import { instantMeiliSearch } from '../src/index.js'
import { meilisearchClient, dataset } from './assets/utils.js'

describe('Custom HTTP client tests', () => {
  beforeAll(async () => {
    await meilisearchClient.deleteIndex('movies').waitTask()

    await meilisearchClient.index('movies').addDocuments(dataset).waitTask()
  })

  test('a custom HTTP client', async () => {
    const httpClient = vi.fn(async function (
      url: RequestInfo | URL,
      init?: RequestInit
    ) {
      const result = await fetch(url, init)
      return await result.json()
    })

    const { searchClient } = instantMeiliSearch(
      'http://localhost:7700',
      'masterKey',
      {
        httpClient,
      }
    )

    const response = await searchClient.search([
      {
        indexName: 'movies',
        params: {
          attributesToRetrieve: [],
          query: 'ariel',
        },
      },
    ])
    expect(httpClient).toHaveBeenCalledTimes(2)
    expect(response.results[0].hits.length).toEqual(1)
  })
})

