import { describe, beforeAll, test, expect } from 'vitest'
import { instantMeiliSearch } from '../src/index.js'
import { dataset, meilisearchClient, type Movies } from './assets/utils.js'

describe('InstantMeiliSearch overridden parameters', () => {
  beforeAll(async () => {
    await meilisearchClient.deleteIndex('movies').waitTask()
    await meilisearchClient.index('movies').addDocuments(dataset).waitTask()
  })

  test('instantiating with, and changing overridden Meilisearch parameters', async () => {
    const { searchClient, setMeiliSearchParams } = instantMeiliSearch(
      'http://localhost:7700',
      'masterKey',
      {
        meiliSearchParams: {
          highlightPreTag: '<em>',
          highlightPostTag: '</em>',
          attributesToSearchOn: ['overview'],
        },
      }
    )

    const queryParams = [
      {
        indexName: 'movies',
        params: { query: '"While racing to a boxing match"' },
      },
    ]
    const firstResponse = await searchClient.search<Movies>(queryParams)

    const firstHits = firstResponse.results[0].hits
    expect(firstHits.length).toEqual(1)
    expect(firstHits[0]._highlightResult?.overview?.value).toContain(
      '<em>While racing to a boxing match</em>'
    )

    setMeiliSearchParams({
      highlightPreTag: '<om>',
      highlightPostTag: '</om>',
    })

    const secondResponse = await searchClient.search<Movies>(queryParams)

    const secondHits = secondResponse.results[0].hits
    expect(secondHits.length).toEqual(1)
    expect(secondHits[0]._highlightResult?.overview?.value).toContain(
      '<om>While racing to a boxing match</om>'
    )

    setMeiliSearchParams({
      indexesOverrides: {
        movies: { highlightPreTag: '<span>', highlightPostTag: '</span>' },
      },
    })
    const thirdResponse = await searchClient.search<Movies>(queryParams)

    const thirdHits = thirdResponse.results[0].hits
    expect(thirdHits.length).toEqual(1)
    expect(thirdHits[0]._highlightResult?.overview?.value).toContain(
      '<span>While racing to a boxing match</span>'
    )
  })

  test('sort parameter precedence: per-index overrides global overrides', async () => {
    await meilisearchClient
      .index('movies')
      .updateSettings({
        sortableAttributes: ['release_date', 'title'],
      })
      .waitTask()

    const { searchClient, setMeiliSearchParams } = instantMeiliSearch(
      'http://localhost:7700',
      'masterKey',
      {
        meiliSearchParams: {
          sort: ['title:asc'],
        },
      }
    )

    const queryParams = [
      {
        indexName: 'movies',
        params: { query: '', hitsPerPage: 3 },
      },
    ]

    // Test global sort override - should sort by title ascending
    const globalResponse = await searchClient.search<Movies>(queryParams)
    const globalHits = globalResponse.results[0].hits
    expect(globalHits.length).toBeGreaterThan(1)
    // Verify titles are sorted in ascending order
    const globalTitles = globalHits
      .map((hit: Movies) => hit.title)
      .filter(Boolean)
    expect(globalTitles).toEqual([...globalTitles].sort())

    // Test per-index sort override takes precedence over global
    setMeiliSearchParams({
      sort: ['title:asc'],
      indexesOverrides: {
        movies: { sort: ['title:desc'] },
      },
    })

    const perIndexResponse = await searchClient.search<Movies>(queryParams)
    const perIndexHits = perIndexResponse.results[0].hits
    expect(perIndexHits.length).toBeGreaterThan(1)
    // Verify titles are sorted in descending order
    const perIndexTitles = perIndexHits
      .map((hit: Movies) => hit.title)
      .filter(Boolean)
    expect(perIndexTitles).toEqual([...perIndexTitles].sort().reverse())
  })
})

import { describe, beforeAll, test, expect } from 'vitest'
import {
  searchClient,
  dataset,
  type Movies,
  meilisearchClient,
} from './assets/utils.js'

describe('Instant Meilisearch Browser test', () => {
  beforeAll(async () => {
    await meilisearchClient.deleteIndex('movies').waitTask()

    await meilisearchClient.index('movies').addDocuments(dataset).waitTask()
  })

  test('attributesToRetrieve on no attributes', async () => {
    const response = await searchClient.search([
      {
        indexName: 'movies',
        params: {
          attributesToRetrieve: [],
          query: 'ariel',
        },
      },
    ])

    const hit = response.results[0].hits[0] as Movies
    expect(hit.id).not.toBeDefined()
    expect(hit.overview).not.toBeDefined()
    expect(hit.genres).not.toBeDefined()
    expect(hit.release_date).not.toBeDefined()
    expect(hit.title).not.toBeDefined()
  })

  test('attributesToRetrieve on null', async () => {
    const response = await searchClient.search([
      {
        indexName: 'movies',
        params: {
          attributesToRetrieve: [],
          query: 'ariel',
        },
      },
    ])

    const hit = response.results[0].hits[0] as Movies
    expect(hit.id).not.toBeDefined()
    expect(hit.overview).not.toBeDefined()
    expect(hit.genres).not.toBeDefined()
    expect(hit.poster).not.toBeDefined()
    expect(hit.release_date).not.toBeDefined()
    expect(hit.title).not.toBeDefined()
  })

  test('attributesToRetrieve on one non existing attribute', async () => {
    const response = await searchClient.search([
      {
        indexName: 'movies',
        params: {
          attributesToRetrieve: ['test'],
          query: 'ariel',
        },
      },
    ])

    const hit = response.results[0].hits[0] as Movies
    expect(hit._highlightResult?.id).toBeDefined()
    expect(hit._highlightResult?.overview).toBeDefined()
    expect(hit._highlightResult?.genres).toBeDefined()
    expect(hit._highlightResult?.poster).toBeDefined()
    expect(hit._highlightResult?.release_date).toBeDefined()
    expect(hit._highlightResult?.title).toBeDefined()
  })

  test('attributesToRetrieve on one existing attribute', async () => {
    const response = await searchClient.search([
      {
        indexName: 'movies',
        params: {
          attributesToRetrieve: ['title'],
          query: 'ariel',
        },
      },
    ])

    const hit = response.results[0].hits[0] as Movies
    expect(hit.title).toEqual('Ariel')
    expect(hit.id).not.toBeDefined()
    expect(hit.overview).not.toBeDefined()
    expect(hit.genres).not.toBeDefined()
    expect(hit.poster).not.toBeDefined()
    expect(hit.release_date).not.toBeDefined()
    expect(hit.title).toBeDefined()
  })

  test('attributesToRetrieve on default value', async () => {
    const response = await searchClient.search([
      {
        indexName: 'movies',
        params: {
          query: 'ariel',
        },
      },
    ])

    const hit = response.results[0].hits[0] as Movies
    expect(hit.title).toEqual('Ariel')
    expect(hit._highlightResult).toBeDefined()
    expect(hit.id).toBeDefined()
    expect(hit.overview).toBeDefined()
    expect(hit.genres).toBeDefined()
    expect(hit.poster).toBeDefined()
    expect(hit.release_date).toBeDefined()
    expect(hit.title).toBeDefined()
    expect(hit._highlightResult?.id).toBeDefined()
    expect(hit._highlightResult?.overview).toBeDefined()
    expect(hit._highlightResult?.genres).toBeDefined()
    expect(hit._highlightResult?.poster).toBeDefined()
    expect(hit._highlightResult?.release_date).toBeDefined()
    expect(hit._highlightResult?.title).toBeDefined()
  })

  test('attributesToRetrieve on wild card', async () => {
    const response = await searchClient.search([
      {
        indexName: 'movies',
        params: {
          query: 'ariel',
          attributesToRetrieve: ['*'],
        },
      },
    ])

    const hit = response.results[0].hits[0] as Movies
    expect(hit.title).toEqual('Ariel')
    expect(hit._highlightResult?.id).toBeDefined()
    expect(hit._highlightResult?.overview).toBeDefined()
    expect(hit._highlightResult?.genres).toBeDefined()
    expect(hit._highlightResult?.poster).toBeDefined()
    expect(hit._highlightResult?.release_date).toBeDefined()
    expect(hit._highlightResult?.title).toBeDefined()
  })
})

import { describe, afterEach, test, expect, vi } from 'vitest'
import type { Movies } from './assets/utils.js'
import {
  instantMeiliSearch,
  type MeilisearchMultiSearchParams,
} from '../src/index.js'
import { Meilisearch } from 'meilisearch'
import pkg from '../package.json' with { type: 'json' }

export const searchResponse = {
  hits: [],
  query: '',
  offset: 0,
  limit: 0,
  processingTimeMs: 0,
  estimatedTotalHits: 0,
  exhaustiveNbHits: false,
}

vi.mock(import('meilisearch'), { spy: true })

function getMeiliSearchMultiSearchSpy(meiliSearch: Meilisearch) {
  return vi
    .spyOn(meiliSearch, 'multiSearch')
    .mockImplementation(function (request) {
      const response = request.queries.map(
        (req: MeilisearchMultiSearchParams) => ({
          ...searchResponse,
          indexUid: req.indexUid,
        })
      )

      return {
        results: response,
      } as any
    })
}

describe('Cached search tests', () => {
  afterEach(() => {
    vi.clearAllMocks()
  })

  test('the same search parameters twice', async () => {
    const searchParameters = {
      indexName: 'movies',
      params: {
        query: '',
      },
    }
    const { searchClient, meiliSearchInstance } = instantMeiliSearch(
      'http://localhost:7700'
    )
    const mockedMultiSearch = getMeiliSearchMultiSearchSpy(meiliSearchInstance)

    await searchClient.search<Movies>([searchParameters])
    await searchClient.search<Movies>([searchParameters])

    expect(Meilisearch).toHaveBeenCalledWith({
      host: 'http://localhost:7700',
      apiKey: '',
      clientAgents: [`Meilisearch instant-meilisearch (v${pkg.version})`],
    })
    expect(mockedMultiSearch).toHaveBeenCalledTimes(2)
  })

  test('two different search parameters', async () => {
    const searchParameters1 = {
      indexName: 'movies',
      params: {
        query: '',
      },
    }

    const searchParameters2 = {
      indexName: 'movies',
      params: {
        query: 'other query',
      },
    }
    const { searchClient, meiliSearchInstance } = instantMeiliSearch(
      'http://localhost:7700'
    )
    const mockedMultiSearch = getMeiliSearchMultiSearchSpy(meiliSearchInstance)

    await searchClient.search<Movies>([searchParameters1])
    await searchClient.search<Movies>([searchParameters2])

    expect(Meilisearch).toHaveBeenCalledWith({
      host: 'http://localhost:7700',
      apiKey: '',
      clientAgents: [`Meilisearch instant-meilisearch (v${pkg.version})`],
    })
    expect(mockedMultiSearch).toHaveBeenCalledTimes(3)
  })

  test('two identical and one different search parameters', async () => {
    const searchParameters1 = {
      indexName: 'movies',
      params: {
        query: '',
      },
    }

    const searchParameters2 = {
      indexName: 'movies',
      params: {
        query: 'other query',
      },
    }
    const { searchClient, meiliSearchInstance } = instantMeiliSearch(
      'http://localhost:7700'
    )
    const mockedMultiSearch = getMeiliSearchMultiSearchSpy(meiliSearchInstance)

    await searchClient.search<Movies>([searchParameters1])
    await searchClient.search<Movies>([searchParameters2])
    await searchClient.search<Movies>([searchParameters1])

    expect(Meilisearch).toHaveBeenCalledWith({
      host: 'http://localhost:7700',
      apiKey: '',
