        '__ais-highlight__hello__/ais-highlight__ world'
      )
    }

    if (hit?.object) {
      expect(hit?.object?.id?.value).toEqual('1')

      expect(hit?.object?.name?.value).toEqual('One two')
    }

    if (hit?.nullField) {
      // @ts-ignore
      expect(hit?.nullField?.value).toEqual('null')
    }
  })
})

